function parseAxiosStyleMessage(msg) {
  if (typeof msg !== 'string' || !msg.trim()) {
    return { httpStatus: null, codigo: null, mensajeNegocio: null, parseOk: false };
  }

  const m = msg.match(/^(\d+)\s*-\s*"([\s\S]*)"\s*$/);
  if (!m) {
    return { httpStatus: null, codigo: null, mensajeNegocio: null, parseOk: false };
  }

  const httpStatus = Number(m[1], 10);
  let inner = m[2];
  inner = inner.replace(/\\"/g, '"').replace(/\\n/g, '\n').trim();

  try {
    const body = JSON.parse(inner);
    const err = body?.error;
    return {
      httpStatus,
      codigo: err?.codigo ?? null,
      mensajeNegocio: err?.mensaje ?? null,
      parseOk: true,
    };
  } catch {
    return { httpStatus, codigo: null, mensajeNegocio: null, parseOk: false };
  }
}

return $input.all().map((item) => {
  const msg = item.json.error?.message;
  const parsed = parseAxiosStyleMessage(msg);

  const tituloCorreo = parsed.mensajeNegocio
    ? `No se pudo verificar el archivo`
    : `Error al verificar el archivo`;

  const resumen =
    parsed.mensajeNegocio ||
    'Ocurrió un problema al procesar la solicitud. El equipo técnico puede revisar el detalle en n8n.';

  return {
    json: {
      ...item.json,
      alerta_verificacion: {
        titulo: tituloCorreo,
        resumen_usuario: resumen,
        codigo_api: parsed.codigo,
        http_status: parsed.httpStatus,
        parse_ok: parsed.parseOk,
      },
    },
  };
});

